import{at as e,bt as t,n,ot as r}from"./chunks/framework.q-HS9miv.js";var i=JSON.parse(`{"title":"Linux setup","description":"","frontmatter":{"title":"Linux setup"},"headers":[],"relativePath":"guide/setup/linux.md","filePath":"guide/setup/linux.md","lastUpdated":1791120943000}`),a={name:`guide/setup/linux.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<h1 id="linux-setup" tabindex="-1">Linux setup <a class="header-anchor" href="#linux-setup" aria-label="Permalink to “Linux setup”">​</a></h1><p>Linux desktop widgets use the same <strong>embedded</strong> webview path as <a href="/tauri-plugin-widgets/guide/setup/desktop">Desktop webview</a>: <code>createWidgetWindow</code> without <code>url</code> (no <code>widget.html</code> copy). Extra Linux behavior is window pinning.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to “How it works”">​</a></h2><ol><li><code>setWidgetConfig</code> writes IR into the desktop file store for <code>(group, widgetId)</code>.</li><li><code>createWidgetWindow</code> opens a frameless Tauri webview on the <code>widgetview</code> protocol.</li><li>With Cargo feature <code>linux</code> (<strong>default</strong>), the plugin sets X11 <code>_NET_WM_WINDOW_TYPE_DESKTOP</code> so the window behaves like a desktop pin.</li><li>Optional feature <code>layer-shell</code> remaps the window onto gtk-layer-shell <strong>Background</strong> on Wayland.</li></ol><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to “Setup”">​</a></h2><ol><li>Keep default features, or enable explicitly:</li></ol><div class="language-toml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tauri-plugin-widgets = { version = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.5&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, features = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;linux&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Wayland:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># tauri-plugin-widgets = { version = &quot;0.5&quot;, features = [&quot;linux&quot;, &quot;layer-shell&quot;] }</span></span></code></pre></div><ol start="2"><li>Allow the window label in capabilities (<code>windows</code> + <code>widgets:default</code>) — <a href="/tauri-plugin-widgets/guide/install#permissions">Install</a>.</li><li>Call <code>createWidgetWindow</code> as in <a href="/tauri-plugin-widgets/guide/first-widget">First widget</a>.</li></ol><p>Contributor harness / debugging: <a href="/tauri-plugin-widgets/contributing/linux-harness">Linux harness</a>.</p><h2 id="when-it-fails" tabindex="-1">When it fails <a class="header-anchor" href="#when-it-fails" aria-label="Permalink to “When it fails”">​</a></h2><ul><li>Enable the <code>linux</code> feature for X11 DESKTOP pinning (<code>default-features = false</code> drops it).</li><li>Wayland: try <code>layer-shell</code>; plain X11 hints will not apply.</li><li>See <a href="/tauri-plugin-widgets/contributing/linux-harness">Linux harness</a> for debugging pinned windows.</li></ul><p>More symptoms: <a href="/tauri-plugin-widgets/guide/troubleshooting">Troubleshooting index</a>.</p>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};